def _rxn(
    id: int, cat: int, sub: str, title: str, eq: str, what_it_does: str,
    chems: list[str], lab_type: str, obs: str,
    complete_ionic: str | None = None, net_ionic: str | None = None,
    red_half: str | None = None, ox_half: str | None = None,
    extra: str | None = None, added: bool = False,
    color_a: str = "#bae6fd", color_b: str = "#e0f2fe", color_prod: str = "#38bdf8",
    precip: str | None = None, gas: str | None = None, flame: str | None = None,
    temp_c: int = 25,
) -> dict:
    return {
        "id": id,
        "category_id": cat,
        "subcategory": sub,
        "title": title,
        "added_essential": added,
        "equations": {
            "molecular": eq,
            "complete_ionic": complete_ionic,
            "net_ionic": net_ionic,
            "reduction_half": red_half,
            "oxidation_half": ox_half,
            "governing": extra,
        },
        "explanation": what_it_does,
        "chemicals": chems,
        "lab": {
            "apparatus": lab_type,
            "observation": obs,
            "color_a": color_a,
            "color_b": color_b,
            "color_prod": color_prod,
            "precipitate_color": precip,
            "gas_label": gas,
            "flame_color": flame,
            "temperature_c": temp_c,
        },
    }


