         red_half=r"\text{MnO}_4^-(aq) + 8\text{H}^+(aq) + 5\text{e}^- \rightarrow \text{Mn}^{2+}(aq) + 4\text{H}_2\text{O}(l)\quad (E^\circ = +1.51\text{ V})",
         ox_half=r"\text{C}_2\text{O}_4^{2-}(aq) \rightarrow 2\text{CO}_2(g) + 2\text{e}^-\quad (E^\circ_{\text{red}} = -0.49\text{ V})",
