def _resolve_chemical(key: str) -> dict:
    """Return enriched chemical metadata for a species key, falling back gracefully if needed."""
    if key in CHEMICALS:
        chem = dict(CHEMICALS[key])
        chem["key"] = key
        return chem
    return {
        "key": key,
        "name": key,
        "formula": key,
        "state": "aq",
        "color": "#38bdf8",
        "vessel": "vial",
        "cid": None,
        "geom": "ion",
        "appearance": f"Chemical species ({key})",
    }


def get_enriched_reactions() -> list:
    """Return all reactions with category metadata and resolved chemical objects."""
    cat_map = {c["id"]: c for c in CATEGORIES}
    out = []
    for rxn in REACTIONS:
        item = dict(rxn)
        cid = rxn["category_id"]
        item["cat_id"] = cid
        item["name"] = rxn["title"]
        item["equation"] = rxn["equations"]["molecular"]
        item["added"] = rxn["added_essential"]
        cat = cat_map.get(cid, {})
        item["category_title"] = cat.get("title", "")
        item["category_short"] = cat.get("short", "")
        item["category_slug"] = cat.get("slug", "")
        item["category_color"] = cat.get("color", "#38bdf8")
        item["chemical_details"] = [_resolve_chemical(k) for k in rxn.get("chemicals", [])]
        out.append(item)
    return out


def get_reaction_by_id(rxn_id: int) -> dict | None:
    """Return a single enriched reaction by its 1-based ID."""
    for rxn in get_enriched_reactions():
        if rxn["id"] == rxn_id:
            return rxn
    return None


def get_all_payload() -> dict:
    """Return the complete reactions catalog, categories, chemical dictionary, and summary table."""
    enriched = get_enriched_reactions()
    cat_counts = {}
    for r in enriched:
        cid = r["category_id"]
        cat_counts[cid] = cat_counts.get(cid, 0) + 1

    categories_out = []
    for c in CATEGORIES:
        c_copy = dict(c)
        c_copy["count"] = cat_counts.get(c["id"], len(CANONICAL_SUMMARY) if c["id"] == 12 else 0)
        categories_out.append(c_copy)

    return {
        "total_reactions": len(enriched),
        "spec_reactions": sum(1 for r in enriched if not r.get("added_essential")),
        "added_reactions": sum(1 for r in enriched if r.get("added_essential")),
        "categories": categories_out,
        "reactions": enriched,
        "canonical_summary": CANONICAL_SUMMARY,
        "chemicals": CHEMICALS,
    }


